export interface ElectionResult2015 {
  party: string
  voteShare: number
  majority: number
  turnout: number
}

export interface Candidate2015 {
  name: string
  party: string
  votes: number
  voteShare: number
  isWinner: boolean
  wasIncumbent: boolean
}

export interface Constituency2015 {
  id: number
  name: string
  region: string
  county: string
  nation: string
  lat: number
  lng: number
  electorate: number
  totalVotes: number
  winner: string
  majority: number
  turnout: number
  candidates: Candidate2015[]
}

